@using sv_cd4f6271340b43c4bd6cf2b8c20138c4.Services

<div class="product-card" @onclick="OnCardClicked">
    <div class="product-image" title="@Product.Name">
        @if (!string.IsNullOrEmpty(Product.ImageUrl))
        {
            <img src="@Product.ImageUrl" alt="@Product.Name" />
        }
        else
        {
            <span class="placeholder-text">@Product.Name</span>
        }
    </div>
    <div class="product-info">
        <h3 class="product-name">@Product.Name</h3>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" title="@($"{Product.Rating:F1} out of 5")">
            @GetStarDisplay(Product.Rating)
        </div>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="OnAddToCartClicked"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task OnCardClicked()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task OnAddToCartClicked()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarDisplay(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

