@page "/catalog"
@using sv_cd4f6271340b43c4bd6cf2b8c20138c4.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-layout">
    @* ── Left Sidebar: Filters ── *@
    <aside class="filter-sidebar">
        <h2>Filters</h2>

        @if (categories is not null)
        {
            <fieldset>
                <legend>Category</legend>
                @foreach (var cat in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        @cat
                    </label>
                }
            </fieldset>
        }

        <fieldset>
            <legend>Price Range</legend>
            <div class="price-inputs">
                <label>
                    Min
                    <input type="number" min="0" step="0.01"
                           @bind="minPrice" @bind:event="onchange" />
                </label>
                <label>
                    Max
                    <input type="number" min="0" step="0.01"
                           @bind="maxPrice" @bind:event="onchange" />
                </label>
            </div>
        </fieldset>

        <label class="filter-checkbox">
            <input type="checkbox" @bind="inStockOnly" />
            In Stock Only
        </label>

        <div class="filter-actions">
            <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ── Main Content ── *@
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert-error">
                <strong>Error:</strong> @errorMessage
                <button class="btn-retry" @onclick="ApplyFilters">Retry</button>
            </div>
        }
        else if (isLoading)
        {
            <div class="loading-indicator">
                <span class="spinner"></span>
                <p>Loading products…</p>
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found matching your filters.</p>
                <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
            </div>
        }
        else
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sort-select">Sort by:</label>
                    <select id="sort-select" @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="showing-label">
                    Showing @(firstItemIndex)–@(lastItemIndex) of @(result.TotalCount) products
                </span>
            </div>

            @* Product Grid *@
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <ProductCard Product="product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            @* Pagination *@
            <nav class="pagination" aria-label="Product pages">
                <button class="page-btn"
                        disabled="@(currentPage <= 1)"
                        @onclick="() => GoToPage(currentPage - 1)">
                    Previous
                </button>

                @for (int i = 1; i <= totalPages; i++)
                {
                    var pageNum = i;
                    <button class="page-btn @(pageNum == currentPage ? "active" : "")"
                            @onclick="() => GoToPage(pageNum)">
                        @pageNum
                    </button>
                }

                <button class="page-btn"
                        disabled="@(currentPage >= totalPages)"
                        @onclick="() => GoToPage(currentPage + 1)">
                    Next
                </button>
            </nav>
        }
    </main>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";

    private PagedResult<Product>? result;
    private int currentPage = 1;
    private const int PageSize = 12;
    private bool isLoading = true;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int firstItemIndex => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * PageSize + 1;

    private int lastItemIndex => result is null
        ? 0
        : (result.Page - 1) * PageSize + result.Items.Count;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await SearchAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = new List<string>();
        }
    }

    private async Task SearchAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        sortBy = "price_asc";
        currentPage = 1;
        await SearchAsync();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await SearchAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > totalPages) return;
        currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

